/* Cross-page documentation search.
 *
 * Reads window.__DOCS_SEARCH (defined by docs/site/search-index.js, generated by
 * scripts/search_index.py) and turns every `.docsearch` container into a search
 * box with a results dropdown that deep-links to `page.html#section`.
 *
 * Why not fetch(): the pages are self-contained and must work from `file://`,
 * where fetch() and ES modules are blocked. The index is a committed script, so
 * a plain <script> tag loads it offline.
 */
(function () {
  var DATA = window.__DOCS_SEARCH || [];

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }

  function terms(q) {
    return q.toLowerCase().split(/[^a-z0-9_.:-]+/).filter(Boolean);
  }

  /* Every term must appear (AND). Title hits weigh more than body hits. */
  function score(rec, ts) {
    var title = (rec.t || "").toLowerCase();
    var body = (rec.x || "").toLowerCase();
    var total = 0;
    for (var i = 0; i < ts.length; i++) {
      var t = ts[i];
      var inTitle = title.indexOf(t) >= 0;
      var inBody = body.indexOf(t) >= 0;
      if (!inTitle && !inBody) return 0;
      total += inTitle ? 6 : 1;
      if (title.indexOf(t) === 0) total += 4;
    }
    return total;
  }

  /* A short window of context around the first matching term. */
  function snippet(rec, ts) {
    var text = rec.x || "";
    var lower = text.toLowerCase();
    var at = -1;
    for (var i = 0; i < ts.length && at < 0; i++) at = lower.indexOf(ts[i]);
    if (at < 0) at = 0;
    var start = Math.max(0, at - 70);
    var out = text.slice(start, start + 210).trim();
    return (start > 0 ? "…" : "") + out + (start + 210 < text.length ? "…" : "");
  }

  function highlight(text, ts) {
    var out = esc(text);
    ts.forEach(function (t) {
      if (!t) return;
      out = out.replace(new RegExp("(" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "gi"),
        "<mark>$1</mark>");
    });
    return out;
  }

  function init(box) {
    var input = box.querySelector("input");
    var panel = box.querySelector(".ds-results");
    if (!input || !panel) return;
    var timer = null;

    function close() { panel.hidden = true; panel.innerHTML = ""; }

    function run() {
      var q = input.value.trim();
      var ts = terms(q);
      if (ts.length === 0) { close(); return; }

      var hits = [];
      for (var i = 0; i < DATA.length; i++) {
        var s = score(DATA[i], ts);
        if (s > 0) hits.push({ rec: DATA[i], s: s });
      }
      hits.sort(function (a, b) { return b.s - a.s; });
      hits = hits.slice(0, 12);

      if (!hits.length) {
        panel.innerHTML = '<div class="ds-empty">No matches for “' + esc(q) + '”.</div>';
        panel.hidden = false;
        return;
      }

      var here = location.pathname.split("/").pop() || "index.html";
      panel.innerHTML = hits.map(function (h) {
        var r = h.rec;
        var same = r.p === here;
        var href = (same ? "" : r.p) + "#" + r.a;
        return '<a class="ds-hit" href="' + esc(href) + '">' +
          '<div class="ds-t">' + highlight(r.t || r.a, ts) + "</div>" +
          '<div class="ds-p">' + esc(r.p) + " · #" + esc(r.a) + "</div>" +
          '<div class="ds-x">' + highlight(snippet(r, ts), ts) + "</div>" +
          "</a>";
      }).join("");
      panel.hidden = false;
    }

    input.addEventListener("input", function () {
      clearTimeout(timer);
      timer = setTimeout(run, 90);
    });
    input.addEventListener("keydown", function (e) {
      if (e.key === "Escape") { input.value = ""; close(); }
      if (e.key === "Enter") {
        var first = panel.querySelector("a.ds-hit");
        if (first) { location.href = first.getAttribute("href"); }
      }
    });
    document.addEventListener("click", function (e) {
      if (!box.contains(e.target)) close();
    });
  }

  function boot() {
    document.querySelectorAll(".docsearch").forEach(init);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
